using System.Collections.ObjectModel;
using System.ComponentModel;
using System.IO;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using Microsoft.Win32;
namespace MRS;
internal sealed class SensorDevice:INotifyPropertyChanged
{
    internal SensorResult Latest;internal SensorDevice(SensorResult result){Latest=result;First=result.Seen;}
    public string Model=>Latest.Model;public string Id=>Latest.Id;public string Frequency=>(Latest.Context.FrequencyHz/1e6)?.ToString("F6")??"";public string Source=>Latest.Context.Source+(Latest.Context.Replay?" · replay":"");public string LastSeen=>Latest.Seen.ToString("HH:mm:ss.fff");public DateTimeOffset First{get;}public long Count{get;private set;}=1;public string Label{get;set;}="";public string Values=>Latest.Summary;public string Integrity=>Latest.Integrity;
    public event PropertyChangedEventHandler? PropertyChanged;
    internal void Update(SensorResult r){Latest=r;Count++;Notify();}internal void Notify()=>PropertyChanged?.Invoke(this,new PropertyChangedEventArgs(null));
}
internal sealed class BurstWave:FrameworkElement
{
    internal double[] Timings=[];internal bool FirstHigh=true;
    protected override void OnRender(DrawingContext dc){base.OnRender(dc);dc.DrawRectangle(new SolidColorBrush(Color.FromRgb(9,15,25)),null,new Rect(RenderSize));if(Timings.Length==0)return;double total=Timings.Sum();if(total<=0)return;var pen=new Pen(Brushes.Turquoise,1);double x=8;bool high=FirstHigh;double previous=ActualHeight*.75;foreach(double t in Timings){double next=x+t/total*Math.Max(1,ActualWidth-16),y=ActualHeight*(high?.25:.75);dc.DrawLine(pen,new Point(x,previous),new Point(x,y));dc.DrawLine(pen,new Point(x,y),new Point(next,y));x=next;previous=y;high=!high;}}
}
public sealed class SensorPanel:UserControl
{
    private readonly SensorPipeline pipeline=new();private readonly ComboBox decoderGain=new(){Width=100,SelectedIndex=0,ToolTip="Digital gain for rtl_433 only; increase for weak signals after filtering. Too much can clip. Applies at next Start."};private readonly ComboBox profile=new(){Width=175,SelectedIndex=0};private readonly Slider margin=new(){Minimum=3,Maximum=30,Value=8,Width=100,TickFrequency=1,IsSnapToTickEnabled=true};private readonly TextBlock status=new(){Foreground=Brushes.Turquoise,TextWrapping=TextWrapping.Wrap};private readonly TextBox detail=new(){Foreground=Brushes.Black,Background=Brushes.White,IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,FontFamily=new FontFamily("Consolas")};private readonly TextBox diagnostics=new(){Foreground=Brushes.Black,Background=Brushes.White,IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,MaxHeight=100};private readonly ObservableCollection<SensorDevice> sensors=[],meters=[];private readonly ObservableCollection<BurstRow> bursts=[];private readonly DataGrid sensorGrid=new(),meterGrid=new(),burstGrid=new();private readonly BurstWave wave=new(){Height=100,Visibility=Visibility.Collapsed};private readonly TextBox alias=new(){Width=170};private readonly TextBlock selectedText=new(){Foreground=Brushes.LightSteelBlue,TextWrapping=TextWrapping.Wrap};private readonly TabControl tabs=new();private string aliasPath="";private Dictionary<string,string> labels=[];private readonly Dictionary<string,SensorDevice> rows=[];private SensorDevice? selected;private readonly System.Windows.Threading.DispatcherTimer timer;
    internal Func<string?>? CanStart;internal Func<long,Task>? Tune;
    private sealed record BurstRow(DateTimeOffset Seen,PacketContext Context,BurstResult Result){public string Time=>Seen.ToString("HH:mm:ss.fff");public string Frequency=>(Context.FrequencyHz/1e6)?.ToString("F6")??"";public string Source=>Context.Source+(Context.Replay?" · replay":"");public string Duration=>$"{Result.DurationMs:0.###} ms";public int Edges=>Result.PulseCount;public string Timing=>$"{Result.MinUs:0.#} / {Result.MedianUs:0.#} / {Result.MaxUs:0.#} µs";public string Notes=>Result.PulseCount<=1?"Envelope activity; too few transitions to identify a protocol":Result.Detail;}
    internal IEnumerable<DataGrid> MonitorTables=>new[]{sensorGrid,meterGrid,burstGrid};
    public SensorPanel(){var root=new DockPanel{Margin=new Thickness(8),Background=new SolidColorBrush(Color.FromRgb(16,23,34))};Content=root;var top=new StackPanel();DockPanel.SetDock(top,Dock.Top);root.Children.Add(top);var controls=new WrapPanel();top.Children.Add(controls);foreach(string p in new[]{"Sensors / remotes","Utility meters","Burst / tone inspection"})profile.Items.Add(p);controls.Children.Add(profile);foreach(string g in new[]{"Gain +0 dB","Gain +12 dB","Gain +24 dB","Gain +36 dB"})decoderGain.Items.Add(g);controls.Children.Add(decoderGain);
        void Button(Panel panel,string text,Action action){var b=new Button{Content=text,Margin=new Thickness(5,0,0,4)};b.Click+=(_,_)=>{try{action();}catch(Exception ex){status.Text=ex.Message;}};panel.Children.Add(b);}
        Button(controls,"Start analysis",()=>{if(CanStart?.Invoke() is {} error){status.Text=error;return;}pipeline.Start(profile.SelectedIndex,margin.Value,Math.Max(0,decoderGain.SelectedIndex)*12);tabs.SelectedIndex=profile.SelectedIndex==1?1:profile.SelectedIndex==2?2:0;status.Text=pipeline.Status;});Button(controls,"Stop",()=>pipeline.Stop());
        var presets=new ComboBox{Width=115,Margin=new Thickness(8,0,0,4),SelectedIndex=0};foreach(string value in new[]{"Tune preset…","315.000 MHz","433.920 MHz","911.600 MHz"})presets.Items.Add(value);controls.Children.Add(presets);Button(controls,"Tune",()=>{long[] hz=[0,315000000,433920000,911600000];if(presets.SelectedIndex>0&&Tune!=null){pipeline.Stop("Tuning; Start analysis afterward");_=Tune(hz[presets.SelectedIndex]);}});
        controls.Children.Add(new TextBlock{Text=" Burst margin",Foreground=Brushes.LightSteelBlue,VerticalAlignment=VerticalAlignment.Center});controls.Children.Add(margin);var ml=new TextBlock{Text="8 dB",Foreground=Brushes.LightSteelBlue,VerticalAlignment=VerticalAlignment.Center};controls.Children.Add(ml);margin.ValueChanged+=(_,_)=>ml.Text=$"{margin.Value:0} dB (next Start)";SliderWheel.Enable(margin,1);
        Button(controls,"Clear observations",()=>{rows.Clear();sensors.Clear();meters.Clear();bursts.Clear();selected=null;detail.Clear();wave.Timings=[];wave.InvalidateVisual();});Button(controls,"Export observations…",Export);
        top.Children.Add(status);top.Children.Add(new TextBlock{Text="Receive only · start SDR or I/Q replay first · selected listening frequency is analysis center. Sensor and meter profiles use raw I/Q, independent of the audio filter/squelch. One profile per receiver. Switching tabs does not change the running profile.",Foreground=Brushes.LightSteelBlue,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,4,0,5)});
        var bottom=new StackPanel();DockPanel.SetDock(bottom,Dock.Bottom);root.Children.Add(bottom);var labelsBar=new WrapPanel();bottom.Children.Add(labelsBar);labelsBar.Children.Add(new TextBlock{Text="Selected device label",Foreground=Brushes.LightSteelBlue,VerticalAlignment=VerticalAlignment.Center});labelsBar.Children.Add(alias);Button(labelsBar,"Save label",()=>{if(selected==null)return;string key=AliasKey(selected.Latest);var next=new Dictionary<string,string>(labels);if(string.IsNullOrWhiteSpace(alias.Text))next.Remove(key);else next[key]=alias.Text.Trim();string temp=aliasPath+".tmp";File.WriteAllText(temp,JsonSerializer.Serialize(next));File.Move(temp,aliasPath,true);labels=next;foreach(var r in rows.Values)if(AliasKey(r.Latest)==key){r.Label=alias.Text.Trim();r.Notify();}});bottom.Children.Add(selectedText);bottom.Children.Add(wave);
        var exp=new Expander{Foreground=Brushes.LightSteelBlue,Header="Raw result / pulse timings",Content=detail,IsExpanded=true};detail.Height=120;bottom.Children.Add(exp);bottom.Children.Add(new Expander{Foreground=Brushes.LightSteelBlue,Header="Decoder diagnostics",Content=diagnostics});
        Grid(sensorGrid,sensors,["Label","Model","Id","Frequency","Values","Integrity","Count","LastSeen","Source"]);Grid(meterGrid,meters,["Label","Model","Id","Frequency","Values","Integrity","Count","LastSeen","Source"]);Grid(burstGrid,bursts,["Time","Frequency","Duration","Edges","Timing","Notes","Source"]);
        tabs.Items.Add(new TabItem{Header="Sensors / remotes",Content=sensorGrid});tabs.Items.Add(new TabItem{Header="Utility meters",Content=meterGrid});tabs.Items.Add(new TabItem{Header="Pulse / burst inspector",Content=burstGrid});root.Children.Add(tabs);tabs.SelectionChanged+=(_,e)=>{if(e.Source==tabs)wave.Visibility=tabs.SelectedIndex==2?Visibility.Visible:Visibility.Collapsed;};
        foreach(var grid in new[]{sensorGrid,meterGrid})grid.SelectionChanged+=(_,_)=>{if(grid.SelectedItem is SensorDevice r){selected=r;alias.Text=r.Label;selectedText.Text=$"{r.Model} · {r.Id} · {r.Source} · labels are user annotations";detail.Text=r.Latest.Json;}};
        burstGrid.SelectionChanged+=(_,_)=>{if(burstGrid.SelectedItem is BurstRow r){selected=null;alias.Clear();wave.Timings=r.Result.Timings;wave.FirstHigh=r.Result.FirstHigh;wave.InvalidateVisual();selectedText.Text=$"Threshold {r.Result.ThresholdDb:0.#} dBFS (relative, not dBm) · time {r.Result.Seconds:0.###} s from analysis start · crossings are not decoded bits";detail.Text=JsonSerializer.Serialize(r,new JsonSerializerOptions{WriteIndented=true});}};
        timer=new(TimeSpan.FromMilliseconds(250),System.Windows.Threading.DispatcherPriority.Background,(_,_)=>Refresh(),Dispatcher);timer.Start();}
    private static void Grid<T>(DataGrid grid,ObservableCollection<T> items,string[] columns){grid.ItemsSource=items;grid.IsReadOnly=true;grid.AutoGenerateColumns=false;grid.SelectionMode=DataGridSelectionMode.Single;grid.EnableRowVirtualization=true;grid.EnableColumnVirtualization=true;grid.Background=new SolidColorBrush(Color.FromRgb(16,23,34));grid.RowBackground=Brushes.WhiteSmoke;grid.AlternatingRowBackground=new SolidColorBrush(Color.FromRgb(228,237,248));grid.Foreground=Brushes.Black;grid.CanUserAddRows=false;grid.HeadersVisibility=DataGridHeadersVisibility.Column;ScrollViewer.SetHorizontalScrollBarVisibility(grid,ScrollBarVisibility.Auto);
        foreach(var c in columns){double width=c switch{"Label"=>110,"Model"=>150,"Id"=>95,"Frequency"=>100,"Count" or "Edges"=>65,"LastSeen" or "Time"=>105,"Integrity"=>160,"Timing"=>180,"Source"=>180,"Duration"=>95,_=>240};var col=new DataGridTextColumn{Header=c,Binding=new System.Windows.Data.Binding(c),MinWidth=Math.Min(width,90),Width=c is "Values" or "Notes"?new DataGridLength(1,DataGridLengthUnitType.Star):new DataGridLength(width)};if(c is "Values" or "Notes"){col.MinWidth=240;var style=new Style(typeof(TextBlock));style.Setters.Add(new Setter(TextBlock.TextWrappingProperty,TextWrapping.Wrap));style.Setters.Add(new Setter(TextBlock.MaxHeightProperty,75.0));col.ElementStyle=style;}grid.Columns.Add(col);}}
    internal void Initialize(string folder){aliasPath=Path.Combine(folder,"sensor-labels.json");try{if(File.Exists(aliasPath))labels=JsonSerializer.Deserialize<Dictionary<string,string>>(File.ReadAllText(aliasPath))??[];}catch(Exception ex){status.Text="Labels not loaded: "+ex.Message;}}
    private static string AliasKey(SensorResult r)=>$"{r.Context.FrequencyHz}:{r.Model}:{r.Id}";
    internal void Feed(IqFrame frame,PacketContext context)=>pipeline.Feed(frame,context);internal void Reset()=>pipeline.Reset();internal Task CompleteAsync()=>pipeline.CompleteAsync();
    private static bool IsMeter(string model)=>model.Contains("ERT",StringComparison.OrdinalIgnoreCase)||model.Contains("SCM",StringComparison.OrdinalIgnoreCase)||model.Contains("IDM",StringComparison.OrdinalIgnoreCase)||model.Contains("ORION",StringComparison.OrdinalIgnoreCase)||model.Contains("Neptune",StringComparison.OrdinalIgnoreCase)||model.Contains("R900",StringComparison.OrdinalIgnoreCase);
    internal void Refresh(){diagnostics.Text=pipeline.Diagnostics;foreach(var r in pipeline.Drain()){if(rows.TryGetValue(r.Key,out var row))row.Update(r);else{var list=IsMeter(r.Model)?meters:sensors;if(rows.Count>=500){var oldest=rows.Values.MinBy(x=>x.Latest.Seen)!;rows.Remove(oldest.Latest.Key);sensors.Remove(oldest);meters.Remove(oldest);}row=new(r){Label=labels.GetValueOrDefault(AliasKey(r),"")};rows.Add(r.Key,row);list.Add(row);}}
        foreach(var r in pipeline.DrainBursts()){if(bursts.Count>=100)bursts.RemoveAt(0);bursts.Add(new(DateTimeOffset.UtcNow,r.Context,r.Burst));}status.Text="Current run: "+pipeline.Status+$" | retained tables: {sensors.Count} sensors / {meters.Count} meters / {bursts.Count} bursts";}
    private void Export(){var picker=new SaveFileDialog{Filter="JSON|*.json",FileName="mrs-sensor-observations.json"};if(picker.ShowDialog()==true)File.WriteAllText(picker.FileName,JsonSerializer.Serialize(new{ExportedUtc=DateTimeOffset.UtcNow,Devices=rows.Values.Select(r=>new{r.Model,r.Id,r.Label,r.Count,r.First,LastSeenUtc=r.Latest.Seen,r.Latest.Context,r.Integrity,r.Values,RawJson=r.Latest.Json}),Bursts=bursts},new JsonSerializerOptions{WriteIndented=true}));}
    internal void Release(){timer.Stop();pipeline.Dispose();}
    internal void ShowSmoke(Action<string> capture,Action show){var context=new PacketContext("synthetic-sensor-ui","Synthetic UI fixture",true,433920000,0);var result=SensorResult.Parse("{\"model\":\"Weather-fixture\",\"id\":42,\"temperature_C\":21.5,\"humidity\":55,\"mic\":\"CHECKSUM\"}",context)!;sensors.Add(new(result){Label="Synthetic weather"});sensorGrid.SelectedIndex=0;tabs.SelectedIndex=0;show();capture("ui-sensors.png");
        meters.Add(new(result with{Model="ERT-SCM fixture",Id="12345",Context=context with{FrequencyHz=911600000},Summary="Raw consumption counter: 1234; device units unconfirmed"}));tabs.SelectedIndex=1;show();capture("ui-utility-meters.png");
        var pulse=new BurstResult(1,22,8,250,500,1000,-50,[250,500,250,1000,250,500,250,1000],"Synthetic pulse fixture","Timing evidence, no protocol inferred");bursts.Add(new(DateTimeOffset.UtcNow,context,pulse));tabs.SelectedIndex=2;burstGrid.SelectedIndex=0;show();if(wave.ActualWidth<100||detail.ActualHeight<60||sensorGrid.Columns.Any(c=>c.ActualWidth<60))throw new InvalidOperationException("Sensor inspector layout is unusable");capture("ui-burst-inspector.png");}

}
public partial class MainWindow
{
    private void InitializeSensors(){Sensors.Initialize(dataFolder);Sensors.CanStart=()=>!rfMode?"Start the SDR receiver or open an I/Q replay first.":receiver.SamplingMode!=0?"Sensor analysis requires quadrature sampling.":null;Sensors.Tune=LiveTune;
        receiver.RawIq+=f=>Sensors.Feed(f,new PacketContext($"sensor:{Interlocked.Read(ref session)}",$"Receiver {workspaceSlot} · "+(receiver.IsReplay?"I/Q recording":receiver.ReceiverName),receiver.IsReplay,f.Channel?.Frequency??f.Frequency,receiver.IsReplay?receiver.ReplayPosition.TotalSeconds:null));receiver.ChannelChanged+=Sensors.Reset;receiver.ReplayGap+=Sensors.Reset;receiver.Ended+=message=>{_=Sensors.CompleteAsync();};}
}
